if ( ! defined( 'ABSPATH' ) ) { exit; }
function kimpu_register_footer_settings( $c ) {
    $c->add_section( 'kimpu_footer', array( 'title' => __( 'Footer Builder', 'kimpu-multipurpose' ), 'priority' => 31 ) );
    $c->add_setting( 'kimpu_footer_layout', array( 'default' => 'default', 'sanitize_callback' => function( $v ) { return in_array( $v, array( 'default', 'centered', 'minimal' ), true ) ? $v : 'default'; } ) ); $c->add_control( 'kimpu_footer_layout', array( 'label' => __( 'Footer Layout', 'kimpu-multipurpose' ), 'section' => 'kimpu_footer', 'type' => 'select', 'choices' => array( 'default' => __( 'Default', 'kimpu-multipurpose' ), 'centered' => __( 'Centered', 'kimpu-multipurpose' ), 'minimal' => __( 'Minimal', 'kimpu-multipurpose' ) ) ) );
    $bools = array( 'kimpu_footer_border' => __( 'Show Footer Border', 'kimpu-multipurpose' ), 'kimpu_footer_logo' => __( 'Show Footer Logo', 'kimpu-multipurpose' ), 'kimpu_social_enabled' => __( 'Show Social Icons', 'kimpu-multipurpose' ) ); foreach ( $bools as $id => $label ) { $c->add_setting( $id, array( 'default' => true, 'sanitize_callback' => 'rest_sanitize_boolean' ) ); $c->add_control( $id, array( 'label' => $label, 'section' => 'kimpu_footer', 'type' => 'checkbox' ) ); }
    $colors = array( 'kimpu_footer_background' => array( '#17283b', __( 'Footer Background', 'kimpu-multipurpose' ) ), 'kimpu_footer_text_color' => array( '#bfcad5', __( 'Footer Text Color', 'kimpu-multipurpose' ) ), 'kimpu_footer_heading_color' => array( '#ffffff', __( 'Footer Heading Color', 'kimpu-multipurpose' ) ) ); foreach ( $colors as $id => $data ) { $c->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => 'sanitize_hex_color' ) ); $c->add_control( new WP_Customize_Color_Control( $c, $id, array( 'label' => $data[1], 'section' => 'kimpu_footer' ) ) ); }
    $text = array( 'kimpu_footer_description' => array( '', __( 'Footer Description', 'kimpu-multipurpose' ), 'textarea', 'sanitize_textarea_field' ), 'kimpu_footer_copyright' => array( '', __( 'Copyright Text', 'kimpu-multipurpose' ), 'text', 'sanitize_text_field' ), 'kimpu_contact_email' => array( '', __( 'Contact Email', 'kimpu-multipurpose' ), 'email', 'sanitize_email' ), 'kimpu_contact_phone' => array( '', __( 'Contact Phone', 'kimpu-multipurpose' ), 'text', 'sanitize_text_field' ), 'kimpu_contact_address' => array( '', __( 'Contact Address', 'kimpu-multipurpose' ), 'text', 'sanitize_text_field' ) ); foreach ( $text as $id => $data ) { $c->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => $data[3] ) ); $c->add_control( $id, array( 'label' => $data[1], 'section' => 'kimpu_footer', 'type' => $data[2] ) ); }
}
